attempts.sop:
@c nlu.clause form=imperative predicate="include" direct_object=$t
@t nlu.entity determiner="a" head="table" modifier="named Budget"
@h nlu.entity head="headings"
@i nlu.entity head="Item"
@cost nlu.entity head="Cost"
@hc nlu.coordination kind=and member=$i member=$cost cue="and"
@rh nlu.relation kind=has_heading from=$t to=$hc cue="with"
@row nlu.entity determiner="the" head="row"
@paper nlu.entity head="Paper"
@num nlu.entity literal="12"
@rc nlu.coordination kind=and member=$paper member=$num cue="and"
@rr nlu.relation kind=has_row from=$t to=$row cue="and"
@rv nlu.relation kind=contains from=$row to=$rc

@c nlu.clause form=imperative predicate="draw" direct_object=$all
@d nlu.entity quantity="three" modifier="small" color=white head="ducks"
@pond nlu.entity determiner="the" head="pond"
@rd nlu.relation kind=location from=$d to=$pond cue="on"
@o nlu.entity determiner="a" modifier="medium" color=brown head="owl"
@tree nlu.entity determiner="the" head="tree"
@ro nlu.relation kind=location from=$o to=$tree cue="on" adverb="right"
@g nlu.entity determiner="a" modifier="small" head="girl"
@face nlu.entity determiner="a" modifier="shocked" head="face"
@rf nlu.relation kind=has from=$g to=$face cue="with"
@rg nlu.relation kind=location from=$g to=$pond cue="next to" adverb="just"
@b nlu.entity determiner="a" modifier="medium" color=brown head="bench"
@part nlu.entity determiner="the" modifier="right" head="part"
@rb nlu.relation kind=location from=$b to=$part cue="in"
@all nlu.coordination kind=and member=$d member=$o member=$g member=$b cue="and"

@p nlu.clause form=fragment expression="Please" separator=","
@c nlu.clause form=imperative predicate="draw" direct_object=$circle
@circle nlu.entity determiner="a" color=blue head="circle"
@call nlu.clause form=imperative predicate="call" direct_object=$it predicative_entity=$name
@it nlu.entity pronoun="it"
@name nlu.entity name="dolphin"
@co nlu.coordination kind=and member=$c member=$call cue="and"
@thanks nlu.clause form=fragment expression="Thanks" terminator="!" speech_act=thanks

@hey nlu.clause form=fragment expression="Hey" separator=","
@c nlu.clause form=imperative predicate="book" direct_object=$room
@room nlu.entity head="Room" quantity="10"
@plan nlu.entity name="Planning"
@r1 nlu.relation kind=purpose from=$c to=$plan cue="for"
@date nlu.entity literal="2026-12-14"
@r2 nlu.relation kind=time from=$c to=$date cue="on"
@time nlu.entity literal="10:00 UTC"
@r3 nlu.relation kind=start_time from=$c to=$time cue="from"
@duration nlu.entity quantity="30" head="minutes"
@r4 nlu.relation kind=duration from=$c to=$duration cue="for"
@help nlu.clause form=declarative subject=$that auxiliary="would" predicate="help"
@that nlu.entity pronoun="That"
